import { AnyOnEventName, ParsedEventHandlers, PointerState, PointerStateWithActive } from "./types.js";
import { Position } from "@solid-primitives/utils";

//#region src/helpers.d.ts
/**
* A non-reactive helper function. It turns a position relative to the screen/window, to be relative to an element.
* @param poz object containing `x` & `y`
* @param el element to calculate the position of
* @returns the `poz` with `x` and `y` changed, and `isInside` added
*/
declare const getPositionToElement: <T extends Position>(poz: T, el: Element) => T & {
  isInside: boolean;
};
declare const parseHandlersMap: <H extends Record<AnyOnEventName, any>>(handlers: H) => ParsedEventHandlers<H>;
declare const toState: (e: PointerEvent) => PointerState;
declare const toStateActive: (e: PointerEvent, isActive: boolean) => PointerState & {
  isActive: boolean;
};
declare const DEFAULT_STATE: PointerStateWithActive;
//#endregion
export { DEFAULT_STATE, getPositionToElement, parseHandlersMap, toState, toStateActive };